// ====== 配置：在这里添加你要监控的商品 ======
const TARGETS = [
  // 示例 1：Shopify 店铺。把域名和商品 handle 换成你的，再把 enabled 改成 true
  {
    enabled: false,
    key: 'shopify-example',                 // 唯一标识，只用英文、数字、横线，配好后不要改
    name: '示例商品（Shopify）',
    type: 'json',
    url: 'https://shop.example.com/products/your-product.js',
    buyUrl: 'https://shop.example.com/products/your-product',
    path: 'available',                      // 库存字段的路径
    inStockWhen: true,                      // 这个字段等于什么值时算有货
  },
  // 示例 2：接口用状态标记表示库存
  {
    enabled: false,
    key: 'json-status-example',
    name: '示例商品（JSON 接口）',
    type: 'json',
    url: 'https://api.example.com/product/123',
    buyUrl: 'https://www.example.com/product/123',
    path: 'data.status',                    // 字段可以是单个值，也可以是数组
    outValues: ['out_of_stock', 'sold_out'],// 出现其中任何一个就算缺货
    restockTimePath: 'data.restock_time',   // 可选：预计补货时间（Unix 秒），临近时自动加快检查
  },
  // 示例 3：普通网页，靠页面上的文字判断
  {
    enabled: false,
    key: 'html-example',
    name: '示例商品（普通网页）',
    type: 'html',
    url: 'https://www.example.com/item/123',
    outOfStockText: ['Sold Out', '缺货', '售罄'], // 页面出现这些字算缺货（优先判断）
    inStockText: ['Add to Cart', '加入购物车'],   // 页面出现这些字算有货
    intervalMinutes: 30,                    // 可选：检查间隔（分钟），默认 15，最小 5
  },
];
// ============================================

// 决定这一轮要查哪些商品。手动运行时查全部；定时运行时按各自的间隔
const MIN_MINUTES = 5;      // 最小检查间隔，请不要调低，以免给对方网站造成压力
const DEFAULT_MINUTES = 15;

const enabled = TARGETS.filter((t) => t.enabled);
const manual = $execution.mode === 'manual';
if (!enabled.length) {
  if (manual) throw new Error('还没有启用任何监控项：请在「监控列表」节点的 TARGETS 里配置商品，并把 enabled 改成 true');
  return [];
}

const keys = enabled.map((t) => t.key);
const bad = enabled.find((t) => !/^[A-Za-z0-9_-]+$/.test(t.key || '') || !/^https?:\/\//.test(t.url || '') || !['json', 'html'].includes(t.type));
if (bad) throw new Error(`监控项配置有误：${bad.name || bad.key}（检查 key、url、type）`);
if (new Set(keys).size !== keys.length) throw new Error('监控项的 key 有重复');

const states = {};
for (const { json } of $('读取上次状态').all()) if (json.key) states[json.key] = json;

const now = Date.now();
return enabled.filter((t) => {
  if (manual) return true;
  const s = states[t.key] || {};
  const last = Date.parse(s.checkedAt || '') || 0;
  const restockAt = Number(s.restockTime || 0) * 1000;
  const near = restockAt > 0 && now >= restockAt - 10 * 60e3 && now <= restockAt + 2 * 3600e3;
  const minutes = near ? MIN_MINUTES : Math.max(MIN_MINUTES, t.intervalMinutes || DEFAULT_MINUTES);
  return now - last >= minutes * 60e3 - 30e3;
}).map((t) => ({ json: t }));

// 判断库存。只有明确识别到状态才算数；识别不了算失败，绝不当作有货
const BROKEN_AFTER = 8; // 连续失败这么多次，发一封「可能失效」提醒

const get = (obj, path) => String(path || '').split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
const pageText = (html) => String(html || '')
  .replace(/<(script|style|noscript)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').toLowerCase();
const has = (text, words) => (words || []).some((w) => text.includes(String(w).toLowerCase()));

const check = (t, res) => {
  if (res.error) return { error: String(res.error.message || res.error).slice(0, 200) };
  const raw = String(res.body ?? '');
  if (/captcha|cf-chl|just a moment|attention required/i.test(raw.slice(0, 5000))) {
    return { error: '页面要求人机验证，无法读取（本工作流不会绕过验证）' };
  }
  if (t.type === 'html') {
    const text = pageText(raw);
    if (has(text, t.outOfStockText)) return { status: 'out_of_stock' };
    if (has(text, t.inStockText)) return { status: 'in_stock' };
    return { error: '页面上没有找到配置的文字，可能是页面改版，或内容由脚本加载' };
  }
  let data;
  try { data = JSON.parse(raw); } catch (e) { return { error: '返回内容不是 JSON' }; }
  const value = get(data, t.path);
  if (value === undefined || value === null) return { error: `返回内容里没有字段 ${t.path}` };
  const restockTime = Number(get(data, t.restockTimePath)) || 0;
  if (Array.isArray(t.outValues)) {
    const values = Array.isArray(value) ? value : [value];
    return { status: values.some((v) => t.outValues.includes(v)) ? 'out_of_stock' : 'in_stock', restockTime };
  }
  if (t.inStockWhen === undefined) return { error: '配置缺少 outValues 或 inStockWhen' };
  return { status: value === t.inStockWhen ? 'in_stock' : 'out_of_stock', restockTime };
};

const states = {};
for (const { json } of $('读取上次状态').all()) if (json.key) states[json.key] = json;

return $input.all().map((item, i) => {
  const t = $('监控列表').itemMatching(i).json;
  const prev = states[t.key] || {};
  const r = check(t, item.json);
  const base = { key: t.key, name: t.name, buyUrl: t.buyUrl || t.url, checkedAt: new Date().toISOString() };

  if (r.error) {
    const failCount = Number(prev.failCount || 0) + 1;
    const warn = failCount >= BROKEN_AFTER && !prev.failWarned;
    return { json: { ...base, status: prev.status || 'unknown', restockTime: Number(prev.restockTime || 0), failCount,
      failWarned: Boolean(prev.failWarned) || warn, notify: warn ? 'broken' : '', reason: r.error } };
  }
  return { json: { ...base, status: r.status, restockTime: r.restockTime || 0, failCount: 0, failWarned: false,
    // 只在「不是有货 → 有货」时通知
    notify: r.status === 'in_stock' && prev.status !== 'in_stock' ? 'restock' : '', reason: '' } };
});

// 把这一轮需要通知的商品合并成一封邮件；没有就到此结束
const all = $('判断状态').all().map((i) => i.json);
const restocked = all.filter((s) => s.notify === 'restock');
const broken = all.filter((s) => s.notify === 'broken');
if (!restocked.length && !broken.length) return [];

const esc = (x) => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
let html = '';
for (const s of restocked) {
  html += `<h3 style="margin:18px 0 10px">${esc(s.name)}</h3><p><a href="${esc(s.buyUrl)}" style="background:#16a34a;color:#fff;padding:10px 24px;border-radius:8px;text-decoration:none;font-weight:600">立即前往购买</a></p>`;
}
if (broken.length) {
  html += '<h3 style="margin:22px 0 8px">⚠️ 以下监控可能失效</h3><p>已连续多次读取不到库存，恢复之前可能收不到补货提醒：</p><ul>' +
    broken.map((s) => `<li><b>${esc(s.name)}</b>：${esc(s.reason)}</li>`).join('') + '</ul>';
}
const names = restocked.map((s) => s.name).join('、');
return [{ json: {
  subject: restocked.length ? `🟢 补货了：${names}` : '⚠️ 补货监控可能失效',
  color: restocked.length ? '#16a34a' : '#d97706',
  title: restocked.length ? '🟢 补货了' : '⚠️ 补货监控可能失效',
  sub: $now.toFormat('yyyy-MM-dd HH:mm'),
  html,
} }];

// 发一封示例提醒，确认邮箱能收到（不查库存，也不改变状态）
return [{ json: {
  subject: '🟢【测试】补货提醒示例', color: '#16a34a', title: '🟢【测试】补货了', sub: '这是一封测试邮件',
  html: '<p>能收到这封邮件，说明发信配置是正常的。</p>',
} }];
